            "また、正しいかみ合わせは、平衡感覚を保つことや、歯を食いしばることによる瞬発力の発揮につながる。歯の喪失は咀嚼能力の低下だけでなく、運動能力の低下につながる。正しいかみあわせの確保や健康な歯の維持が必要となる。",
